package com.bank.mapping.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id", length = 20)
    private String accountId;

    @Column(name = "first_name", nullable = false, length = 50)
    private String firstName;

    @Column(name = "last_name", nullable = false, length = 50)
    private String lastName;

    @Column(name = "savings_balance", nullable = false, precision = 15, scale = 2)
    private BigDecimal savingsBalance;

    @Column(name = "current_balance", nullable = false, precision = 15, scale = 2)
    private BigDecimal currentBalance;

    @Column(name = "pan_number", unique = true, length = 10)
    private String panNumber;

    @Column(columnDefinition = "TEXT")
    private String address;

    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt;

    // ═══ JPA @Transient: NOT mapped to any DB column! ═══
    @Transient
    private String fullName;  // computed: firstName + " " + lastName

    @Transient
    private BigDecimal totalBalance;  // computed: savings + current

    // ═══ @PostLoad: compute transient fields after loading from DB ═══
    @PostLoad
    public void onLoad() {
        this.fullName = firstName + " " + lastName;
        this.totalBalance = savingsBalance.add(currentBalance);
    }

    protected Account() {}

    public String getAccountId() { return accountId; }
    public String getFirstName() { return firstName; }
    public String getLastName() { return lastName; }
    public BigDecimal getSavingsBalance() { return savingsBalance; }
    public BigDecimal getCurrentBalance() { return currentBalance; }
    public String getPanNumber() { return panNumber; }
    public String getFullName() { return fullName; }
    public BigDecimal getTotalBalance() { return totalBalance; }
    public LocalDateTime getCreatedAt() { return createdAt; }
}
```

