// ─── File: src/test/java/com/bank/mapping/ColumnMappingTest.java ───
package com.bank.mapping;

import org.junit.jupiter.api.Test;
import jakarta.persistence.Column;
import jakarta.persistence.Transient;
import java.lang.reflect.Field;
import static org.assertj.core.api.Assertions.*;

class ColumnMappingTest {

    @Test
    void columnAnnotation_customizesMapping() throws Exception {
        Field field = com.bank.mapping.model.Account.class.getDeclaredField("firstName");
        Column col = field.getAnnotation(Column.class);
        assertThat(col.name()).isEqualTo("first_name");
        assertThat(col.nullable()).isFalse();
        assertThat(col.length()).isEqualTo(50);
    }

    @Test
    void panNumber_isUnique() throws Exception {
        Field field = com.bank.mapping.model.Account.class.getDeclaredField("panNumber");
        Column col = field.getAnnotation(Column.class);
        assertThat(col.unique()).isTrue();
        assertThat(col.length()).isEqualTo(10);
    }

    @Test
    void transientFields_notMappedToDb() throws Exception {
        Field fullName = com.bank.mapping.model.Account.class.getDeclaredField("fullName");
        assertThat(fullName.isAnnotationPresent(Transient.class)).isTrue();
        // @Transient → no DB column exists for fullName

        Field totalBalance = com.bank.mapping.model.Account.class.getDeclaredField("totalBalance");
        assertThat(totalBalance.isAnnotationPresent(Transient.class)).isTrue();
        // @Transient → no DB column exists for totalBalance
    }

    @Test
    void jpaTransientVsJavaTransient() {
        // JPA @Transient (jakarta.persistence.Transient):
        //   → Hibernate IGNORES the field. No column. No read/write.
        //   → Use for: computed fields (fullName, totalBalance)

        // Java transient keyword:
        //   → ObjectOutputStream SKIPS the field during serialization
        //   → Hibernate STILL maps it to a column! DB has the column!
        //   → Use for: serialization control ONLY

        // DON'T confuse them:
        // @Transient BigDecimal totalBalance;  → NO DB column (Recommended) (correct for computed)
        // transient BigDecimal totalBalance;   → DB column EXISTS! (Avoid) (wrong for computed)
        assertThat(true).isTrue();
    }

    @Test
    void createdAt_updatable_false() throws Exception {
        Field field = com.bank.mapping.model.Account.class.getDeclaredField("createdAt");
        Column col = field.getAnnotation(Column.class);
        assertThat(col.updatable()).isFalse();
        // updatable=false: Hibernate writes on INSERT but NEVER on UPDATE.
        // createdAt is set once and never changed.
    }
}
```
